p=Path(__file__).parent/'body-attempt-2';board=Image.open(p.parent/'references/board-review-background.png').convert('RGBA');poses=['idle','anticipation','release','recovery'];durations=[500,180,100,180];frames=[]
for pose in poses:
 panel=Image.new('RGB',(720,410),'#09131e');d=ImageDraw.Draw(panel);d.text((16,12),'Popo v6 / ONE letter layer / ART-ONLY choreography, not engine anticipation or flight',fill='white')
 for i,h in enumerate([32,36]):
  im=Image.open(p/'previews'/f'{pose}-{h}px-composite.png');s=h/563;x=round(133-360*s);y=round(133+h/2-(640*s-0.375));b=board.copy();b.alpha_composite(im,(x,y));panel.paste(b.convert('RGB'),(20+i*360,65));d.text((20+i*360,40),f'{h}px body | {pose}',fill='white')
 frames.append(panel)
frames[0].save(p/'art-cycle-32-36.gif',save_all=True,append_images=frames[1:],duration=durations,loop=0,disposal=2)
