bg='data:image/png;base64,'+base64.b64encode((p.parent/'references/board-review-background.png').read_bytes()).decode();assets={str(h):{n:'data:image/png;base64,'+base64.b64encode((p/'previews'/f'{n}-{h}px-composite.png').read_bytes()).decode() for n in poses} for h in [32,36]}
html='''<!doctype html><meta charset="utf-8"><title>Popo v6 art-only cycle</title><style>body{background:#09131e;color:white;font:14px sans-serif;margin:20px}.board{display:inline-block;position:relative;width:320px;height:320px;margin:15px;background-image:url(BG)}.sprite{position:absolute}button{margin:8px}</style><h2>Popo v6 art-only choreography</h2><p>Distinct anticipation and single separate letter shown for art review only. No engine anticipation, moving projectile or hit approval.</p><p>idle500ms / anticipation180ms / release100ms / recovery180ms. Same body scale, no whole-body mirroring.</p><button id="toggle">Pause</button><button id="step">Next</button><span id="label"></span><div><div class="board"><img id="s32" class="sprite" style="left:113px;top:113px;width:55px;height:44px"></div><div class="board"><img id="s36" class="sprite" style="left:110px;top:110px;width:61px;height:49px"></div></div><p>Left32px / right36px body. These are static board crops and a proposed art cycle, not actual combat.</p><script>const assets=ASSETS;const poses=['idle','anticipation','release','recovery'],durations=[500,180,100,180];let index=0,playing=true,last=performance.now();function draw(){s32.src=assets['32'][poses[index]];s36.src=assets['36'][poses[index]];label.textContent=poses[index]+' '+durations[index]+'ms';document.body.dataset.pose=poses[index];}draw();function tick(t){if(playing&&t-last>=durations[index]){last+=durations[index];index=(index+1)%4;draw();}requestAnimationFrame(tick);}requestAnimationFrame(tick);toggle.onclick=()=>{playing=!playing;last=performance.now();toggle.textContent=playing?'Pause':'Play';};step.onclick=()=>{playing=false;toggle.textContent='Play';index=(index+1)%4;draw();};</script>'''.replace('BG',bg).replace('ASSETS',json.dumps(assets));(p/'art-cycle-viewer.html').write_text(html);gif=Image.open(p/'art-cycle-32-36.gif');ds=[]
for i in range(gif.n_frames):gif.seek(i);ds.append(gif.info['duration'])
assert ds==durations; print({'decoded_frames':gif.n_frames,'durations_ms':ds,'actual_browser_playback':False})
